        public var state: VersionState
        public var wordCount: Int
        public var workId: String
        /// Whether this is the work's pinned snapshot.
        public var pinned: Bool
        /// Tags, but not the manifest: a list of fifty snapshots has no use for
        /// fifty manifests.
        public var tags: [String]

        public init(
            createdAt: String,
            createdBy: String,
            finalizedAt: String? = nil,
            id: String,
            label: String,
            notes: String? = nil,
            number: Int,
            parentVersionId: String? = nil,
            publishedAt: String? = nil,
            scope: PublicationScope,
            scopeRefId: String? = nil,
            state: VersionState,
            wordCount: Int,
            workId: String,
            pinned: Bool,
            tags: [String]
        ) {
            self.createdAt = createdAt
            self.createdBy = createdBy
            self.finalizedAt = finalizedAt
            self.id = id
            self.label = label
            self.notes = notes
            self.number = number
            self.parentVersionId = parentVersionId
            self.publishedAt = publishedAt
            self.scope = scope
            self.scopeRefId = scopeRefId
            self.state = state
            self.wordCount = wordCount
            self.workId = workId
            self.pinned = pinned
            self.tags = tags
        }
    }

    public enum Visibility: String, Codable, CaseIterable, Hashable, Sendable {
        case invited = "invited"
        case unlisted = "unlisted"
        case platform = "platform"
        case `public` = "public"
    }

    public struct VoteRequest: Codable, Hashable, Sendable {
        /// `1` upvote, `-1` downvote, `0` clears the caller's vote.
        public var value: Int

        public init(
            value: Int
        ) {
            self.value = value
        }
    }

    public struct VoteResponse: Codable, Hashable, Sendable {
        public var commentId: String
        public var score: Int
        public var viewerVote: Int

        public init(
            commentId: String,
            score: Int,
            viewerVote: Int
        ) {
            self.commentId = commentId
            self.score = score
            self.viewerVote = viewerVote
        }
    }

    public struct Work: Codable, Hashable, Sendable {
        public var copyrightLine: String?
        public var createdAt: String
        public var currentVersionId: String?
        public var dedication: String?
        public var epigraph: String?
        public var epigraphSource: String?
        public var id: String
        public var kind: WorkKind
        public var ownerId: String
        /// The name on the byline, when it is not the writer's own.
        public var penName: String?
        /// The snapshot the writer wants to find without looking — what they last
        /// sent out.
        public var pinnedVersionId: String?
        /// Short form for a running header; a long title wraps and ruins it.
        public var shortTitle: String?
        public var status: WorkStatus
        public var subtitle: String?
        public var synopsis: String?
        public var templateId: String?
        public var title: String
        public var updatedAt: String
        public var wordCount: Int

        public init(
            copyrightLine: String? = nil,
            createdAt: String,
            currentVersionId: String? = nil,
            dedication: String? = nil,
            epigraph: String? = nil,
            epigraphSource: String? = nil,
            id: String,
            kind: WorkKind,
            ownerId: String,
            penName: String? = nil,
            pinnedVersionId: String? = nil,
            shortTitle: String? = nil,
            status: WorkStatus,
            subtitle: String? = nil,
            synopsis: String? = nil,
            templateId: String? = nil,
            title: String,
            updatedAt: String,
            wordCount: Int
        ) {
            self.copyrightLine = copyrightLine
            self.createdAt = createdAt
            self.currentVersionId = currentVersionId
            self.dedication = dedication
            self.epigraph = epigraph
            self.epigraphSource = epigraphSource
            self.id = id
            self.kind = kind
            self.ownerId = ownerId
            self.penName = penName
            self.pinnedVersionId = pinnedVersionId
            self.shortTitle = shortTitle
            self.status = status
            self.subtitle = subtitle
            self.synopsis = synopsis
            self.templateId = templateId
            self.title = title
            self.updatedAt = updatedAt
            self.wordCount = wordCount
        }
    }

    public enum WorkKind: String, Codable, CaseIterable, Hashable, Sendable {
        case novel = "novel"
        case novella = "novella"
        case short_story = "short_story"
        case serial = "serial"
    }

    public enum WorkStatus: String, Codable, CaseIterable, Hashable, Sendable {
        case draft = "draft"
        case published = "published"
        case final = "final"
        case archived = "archived"
    }

    public struct WritingDay: Codable, Hashable, Sendable {
        public var createdAt: String
        /// The writer's local date, `YYYY-MM-DD`.
        public var day: String
        public var id: String
        public var netWords: Int
        public var saves: Int
        public var updatedAt: String
        public var userId: String

        public init(
            createdAt: String,
            day: String,
            id: String,
            netWords: Int,
            saves: Int,
            updatedAt: String,
            userId: String
        ) {
            self.createdAt = createdAt
            self.day = day
            self.id = id
            self.netWords = netWords
            self.saves = saves
            self.updatedAt = updatedAt
            self.userId = userId
        }
    }

    public struct WritingSummary: Codable, Hashable, Sendable {
        /// The writer's target, if they have set one.
        public var dailyWordGoal: Int?
        /// Most recent first, one entry per day the writer showed up.
        public var history: [WritingDay]
        public var savesToday: Int
        /// Consecutive days up to and including today on which they wrote.
        public var streak: Int
        public var today: String
        /// Net words on `today`, which may be negative on a day spent cutting.
        public var wordsToday: Int

        public init(
            dailyWordGoal: Int? = nil,
            history: [WritingDay],
            savesToday: Int,
            streak: Int,
            today: String,
            wordsToday: Int
        ) {
            self.dailyWordGoal = dailyWordGoal
            self.history = history
            self.savesToday = savesToday
            self.streak = streak
            self.today = today
            self.wordsToday = wordsToday
        }
    }
}
